	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	mon := monsters[0]
	ch.X, ch.Y = mon.X-1, mon.Y
	dir := 2 // east, matching the (-1, 0) offset to the monster
	server, client := net.Pipe()
	defer server.Close()
	defer client.Close()
