func TestHandleHitBroadcastsDeathWhenMonsterHPReachesZero(t *testing.T) {
	s := newTestServer(t)
	mapID, x, y := testDefaultSpawn(t)
	ch, err := s.world.CreateCharacterWithAppearance("test", "tester", "warrior", 0, 0, mapID, x, y)
	if err != nil {
		t.Fatalf("CreateCharacter() error = %v", err)
	}
	ch.BonusAbil.Hit = 100
	ch.BonusAbil.DC = 60
	monsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	mon := monsters[0]
	if mon.HP != 5 {
		t.Fatalf("test monster HP = %d, want 5", mon.HP)
	}
	ch.X, ch.Y = mon.X-1, mon.Y
	dir := 2
	server, client := net.Pipe()
	defer server.Close()
	defer client.Close()
	s.registerClient(server, ch)
	defer s.unregisterClient(server)

	for i := 1; i <= 2; i++ {
		recog := int32(uint32(ch.X) | uint32(ch.Y)<<16)
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleHit(server, &ch, mir176.Command{Ident: mir176.CMHit, Recog: recog, Tag: uint16(dir)})
		}()

		if i == 2 {
			var sawStruck, sawAck bool
			for frameNo := 0; frameNo < 2; frameNo++ {
				frame := readFrame(t, client)
				if body, err := mir176.UnwrapFrame(frame); err == nil && strings.HasPrefix(string(body), "+GOOD/") {
					sawAck = true
					continue
				}
				cmd, _, err := decodeMessageLikeClient(frame)
				if err != nil {
					t.Fatalf("decode frame %d error: %v", frameNo, err)
				}
				switch cmd.Ident {
				case mir176.SMStruck:
					sawStruck = true
					if cmd.Recog != world.MonsterActorID(mon) || cmd.Param != 0 || cmd.Tag != uint16(mon.MaxHP) {
						t.Fatalf("struck command = %+v, want target fields", cmd)
					}
				}
			}
			if !sawStruck || !sawAck {
				t.Fatalf("deferred death frames seen struck=%v ack=%v", sawStruck, sawAck)
			}
		} else {
			assertActionAck(t, readFrame(t, client))
			struckCmd, _, err := decodeMessageLikeClient(readFrame(t, client))
			if err != nil {
				t.Fatalf("decode struck frame %d error = %v", i, err)
			}
			wantHP := mon.HP - i*3
			if wantHP < 0 {
				wantHP = 0
			}
			if struckCmd.Ident != mir176.SMStruck || struckCmd.Recog != world.MonsterActorID(mon) || struckCmd.Param != uint16(wantHP) || struckCmd.Tag != uint16(mon.MaxHP) {
				t.Fatalf("struck frame %d = %+v, want target fields %d/%d", i, struckCmd, wantHP, mon.MaxHP)
			}
		}
		<-done
		if i == 2 {
			tickNow := time.Now().Add(2 * time.Second)
			tick, err := s.world.Tick(s.PlayerSnapshots(), tickNow)
			if err != nil {
				t.Fatalf("Tick() error = %v", err)
			}
			s.applyWorldTick(tick, tickNow)
			var sawWinExp, sawDeath, sawDrop bool
			winExpFrame, deathFrame := -1, -1
			for frameNo := 0; frameNo < 16; frameNo++ {
				frame, ok := readFrameWithTimeout(t, client, 200*time.Millisecond)
				if !ok {
					break
				}
				if body, err := mir176.UnwrapFrame(frame); err == nil && strings.HasPrefix(string(body), "+GOOD/") {
					continue
				}
				cmd, body, err := decodeMessageLikeClient(frame)
				if err != nil {
					t.Fatalf("deferred death frame %d error: %v", frameNo, err)
				}
				switch cmd.Ident {
				case mir176.SMWinExp:
					sawWinExp = true
					winExpFrame = frameNo
				case mir176.SMNowDeath:
					sawDeath = true
					deathFrame = frameNo
					assertCharDesc(t, body, world.MonsterFeature(mon), 0)
				case mir176.SMItemShow:
					sawDrop = true
				}
			}
			if !sawWinExp || !sawDeath || sawDrop {
				t.Fatalf("deferred death frames seen winExp=%v death=%v drop=%v", sawWinExp, sawDeath, sawDrop)
			}
			if !(winExpFrame < deathFrame) {
				t.Fatalf("deferred death frame order = exp:%d death:%d, want experience then death", winExpFrame, deathFrame)
			}
		}
	}
}

func TestHandleSpecialHitsBroadcastDeathSequence(t *testing.T) {
	cases := []struct {
		name  string
		ident uint16
		skill string
		armed bool
		dist  int
		wideY int
	}{
		{name: "heavy", ident: mir176.CMHeavyHit},
		{name: "big", ident: mir176.CMBigHit},
		{name: "power", ident: mir176.CMPowerHit, skill: "攻杀剑术", armed: true},
		{name: "long", ident: mir176.CMLongHit, skill: "刺杀剑术", dist: 1},
		{name: "wide", ident: mir176.CMWideHit, skill: "半月弯刀", wideY: -1},
		{name: "fire", ident: mir176.CMFireHit, skill: "烈火剑法", armed: true},
		{name: "cr", ident: mir176.CMCRHit},
		{name: "twin", ident: mir176.CMTwinHit},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s, ch, server, client := newGuaranteedDropServer(t)
			defer server.Close()
			defer client.Close()
			defer s.unregisterClient(server)
			monsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
			if len(monsters) != 1 {
				t.Fatalf("monsters = %d, want one", len(monsters))
			}
			mon := monsters[0]
			ch.X = mon.X - tc.dist - 1
			ch.Y = mon.Y
			if tc.wideY != 0 {
				ch.X = mon.X - 1
				ch.Y = mon.Y + tc.wideY
			}
			ch.BonusAbil.Hit = 100
			ch.BonusAbil.DC = 170
			ch.MP = 100
			if tc.skill != "" {
				ch.Skills = storage.SkillStates{{ID: tc.skill, Level: 0}}
			}
			if tc.armed {
				if tc.ident == mir176.CMPowerHit {
					ch.PowerHitArmed = true
				} else {
					ch.FireHitArmed = true
				}
			}
			recog := int32(uint32(ch.X) | uint32(ch.Y)<<16)
			done := make(chan struct{})
			go func() {
				defer close(done)
				s.handleHit(server, &ch, mir176.Command{Ident: tc.ident, Recog: recog, Tag: 2})
			}()
			if _, ok := readFrameWithTimeout(t, client, time.Second); !ok {
				t.Fatal("timed out waiting for attack output")
			}
			<-done
			tickNow := time.Now().Add(2 * time.Second)
			tick, err := s.world.Tick(s.PlayerSnapshots(), tickNow)
			if err != nil {
				t.Fatal(err)
			}
			s.applyWorldTick(tick, tickNow)
			seenExp, seenDeath, seenDrop := false, false, false
			for {
				frame, ok := readFrameWithTimeout(t, client, 300*time.Millisecond)
				if !ok {
					break
				}
				body, unwrapErr := mir176.UnwrapFrame(frame)
				if unwrapErr == nil && strings.HasPrefix(string(body), "+") {
					continue
				}
				cmd, _, decodeErr := decodeMessageLikeClient(frame)
				if decodeErr != nil {
					continue
				}
				switch cmd.Ident {
				case mir176.SMWinExp:
					seenExp = true
				case mir176.SMItemShow:
					seenDrop = true
				case mir176.SMNowDeath:
					seenDeath = true
				}
			}
			if !seenExp || !seenDrop || !seenDeath {
				t.Fatalf("death sequence for %s: exp=%t drop=%t death=%t", tc.name, seenExp, seenDrop, seenDeath)
			}
		})
	}
}

func TestHandleHitBroadcastsDropWhenMonsterDies(t *testing.T) {
	s, ch, server, client := newGuaranteedDropServer(t)
	defer server.Close()
	defer client.Close()
	defer s.unregisterClient(server)

	monsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	mon := monsters[0]
	ch.X, ch.Y = mon.X-1, mon.Y
	dir := 2

	recog := int32(uint32(ch.X) | uint32(ch.Y)<<16)
	done := make(chan struct{})
	go func() {
		defer close(done)
		s.handleHit(server, &ch, mir176.Command{Ident: mir176.CMHit, Recog: recog, Tag: uint16(dir)})
	}()

	ackSeen := false
	initialFrames := make([][]byte, 0, 2)
	for i := 0; i < 2; i++ {
		frame := readFrame(t, client)
		initialFrames = append(initialFrames, frame)
		if body, err := mir176.UnwrapFrame(frame); err == nil && strings.HasPrefix(string(body), "+GOOD/") {
			ackSeen = true
		}
	}
	if !ackSeen {
		t.Fatal("missing caster action ack")
	}
	<-done
	tickNow := time.Now().Add(2 * time.Second)
	tick, err := s.world.Tick(s.PlayerSnapshots(), tickNow)
	if err != nil {
		t.Fatalf("Tick() error = %v", err)
	}
	s.applyWorldTick(tick, tickNow)
	var sawStruck, sawWinExp, sawDeath, sawDrop bool
	eventOrder := make([]int, 0, 4)
	var showCmd mir176.Command
	var showBody []byte
	for _, frame := range initialFrames {
		cmd, body, err := decodeMessageLikeClient(frame)
		if err != nil {
			continue
		}
		switch cmd.Ident {
		case mir176.SMStruck:
			sawStruck = true
			eventOrder = append(eventOrder, 1)
		case mir176.SMWinExp:
			sawWinExp = true
			eventOrder = append(eventOrder, 2)
		case mir176.SMNowDeath:
			sawDeath = true
			eventOrder = append(eventOrder, 4)
		case mir176.SMItemShow:
			sawDrop = true
			eventOrder = append(eventOrder, 3)
			showCmd = cmd
			showBody = body
		}
	}
	deadline := time.Now().Add(time.Second)
	for time.Now().Before(deadline) {
		frame, ok := readFrameWithTimeout(t, client, 100*time.Millisecond)
		if !ok {
			break
		}
		cmd, body, err := decodeMessageLikeClient(frame)
		if err != nil {
			t.Fatalf("decode frame error = %v", err)
		}
		switch cmd.Ident {
		case mir176.SMStruck:
			sawStruck = true
			eventOrder = append(eventOrder, 1)
		case mir176.SMWinExp:
			sawWinExp = true
			eventOrder = append(eventOrder, 2)
		case mir176.SMNowDeath:
			sawDeath = true
			eventOrder = append(eventOrder, 4)
		case mir176.SMItemShow:
			sawDrop = true
			eventOrder = append(eventOrder, 3)
			showCmd = cmd
			showBody = body
		}
	}
	if !sawStruck || !sawWinExp || !sawDeath || !sawDrop {
		t.Fatalf("frames seen struck=%v winExp=%v death=%v drop=%v", sawStruck, sawWinExp, sawDeath, sawDrop)
	}
	first := func(kind int) int {
		for index, event := range eventOrder {
			if event == kind {
				return index
			}
		}
		return -1
	}
	if !(first(2) < first(3) && first(3) < first(4)) {
		t.Fatalf("immediate death frame order = %v, want experience then drop then death", eventOrder)
	}
	dx := int(showCmd.Param) - mon.X
	dy := int(showCmd.Tag) - mon.Y
	if dx < -3 || dx > 3 || dy < -3 || dy > 3 {
		t.Fatalf("drop show command = %+v, want near monster death at (%d,%d)", showCmd, mon.X, mon.Y)
	}
	weapon, ok := s.world.Item(testWeaponID)
	if !ok {
		t.Fatalf("world.Item(%q) missing", testWeaponID)
	}
	if showCmd.Series != uint16(weapon.Looks) {
		t.Fatalf("drop show looks = %d, want %d from item looks", showCmd.Series, weapon.Looks)
	}
	text, err := mir176.DecodePlain6Payload(showBody)
	if err != nil {
		t.Fatalf("DecodePlain6Payload() error = %v", err)
	}
	if got := DecodeString(text); got != "木剑" {
		t.Fatalf("drop name = %q, want 木剑", got)
	}
	<-done
}

func TestHandleHitBroadcastsAttackerActionToObservers(t *testing.T) {
	s := newTestServer(t)
	s.hitImpactDelay = 25 * time.Millisecond
	mapID, x, y := testDefaultSpawn(t)
	ch, err := s.world.CreateCharacterWithAppearance("test", "tester", "warrior", 0, 0, mapID, x, y)
	if err != nil {
		t.Fatalf("CreateCharacter() error = %v", err)
	}
	ch.BonusAbil.Hit = 100
	ch.FireHitArmed = true
	ch.FireHitLatestAt = time.Now().UnixNano()
	monsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	mon := monsters[0]
	ch.X, ch.Y = mon.X-1, mon.Y
	dir := 2
	observer := ch
	observer.ID = "observer"
	observer.Account = "observer"
	observer.Name = "observer"

	attackerServer, attackerClient := net.Pipe()
	defer attackerServer.Close()
	defer attackerClient.Close()
	observerServer, observerClient := net.Pipe()
	defer observerServer.Close()
	defer observerClient.Close()
	s.registerClient(attackerServer, ch)
	defer s.unregisterClient(attackerServer)
	s.registerClient(observerServer, observer)
	defer s.unregisterClient(observerServer)
	if client := s.clientForConn(attackerServer); client != nil {
		client.mu.Lock()
		client.fireHitArmed = true
		client.fireHitLatestAt = time.Now()
		client.mu.Unlock()
	}

	recog := int32(uint32(ch.X) | uint32(ch.Y)<<16)
	done := make(chan struct{})
	go func() {
		defer close(done)
		s.handleHit(attackerServer, &ch, mir176.Command{Ident: mir176.CMFireHit, Recog: recog, Tag: uint16(dir)})
	}()

	assertActionAck(t, readFrame(t, attackerClient))
	actionCmd, _, err := decodeMessageLikeClient(readFrame(t, observerClient))
	if err != nil {
		t.Fatalf("decode hit action frame error = %v", err)
	}
	if actionCmd.Ident != mir176.SMFireHit || actionCmd.Recog != ActorID || int(actionCmd.Param) != ch.X || int(actionCmd.Tag) != ch.Y || int(actionCmd.Series) != dir {
		t.Fatalf("hit action = %+v, want SM_FIREHIT from attacker at (%d,%d) dir=%d", actionCmd, ch.X, ch.Y, dir)
	}
	<-done
	if ch.FireHitArmed {
		t.Fatal("character fire state remains armed after hit")
	}
	readFrame(t, attackerClient)
	readFrame(t, observerClient)
}

func TestHandleHitRestoresCachedFireStateBeforeWorldAttack(t *testing.T) {
	s := newTestServer(t)
	mapID, x, y := testDefaultSpawn(t)
	ch, err := s.world.CreateCharacterWithAppearance("test", "tester", "warrior", 0, 0, mapID, x, y)
	if err != nil {
		t.Fatalf("CreateCharacter() error = %v", err)
	}
	ch.BonusAbil.Hit = 100
	ch.BonusAbil.DC = 100
	ch.Skills = storage.SkillStates{{ID: "烈火剑法", Level: 0, Train: 0}}
	monsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
	if len(monsters) == 0 {
		t.Fatalf("expected monsters")
	}
	mon := monsters[0]
	initialMonsterHP := mon.HP
	ch.X, ch.Y = mon.X-1, mon.Y
	server, clientConn := net.Pipe()
	defer server.Close()
	defer clientConn.Close()
	s.registerClient(server, ch)
	defer s.unregisterClient(server)
	client := s.clientForConn(server)
	if client == nil {
		t.Fatal("client state = nil")
	}
	client.mu.Lock()
	client.fireHitArmed = true
	client.fireHitLatestAt = time.Now()
	client.mu.Unlock()

	recog := int32(uint32(ch.X) | uint32(ch.Y)<<16)
	done := make(chan struct{})
	go func() {
		defer close(done)
		s.handleHit(server, &ch, mir176.Command{Ident: mir176.CMFireHit, Recog: recog, Tag: 2})
	}()
	deadline := time.Now().Add(time.Second)
	if err := clientConn.SetReadDeadline(deadline); err != nil {
		t.Fatalf("SetReadDeadline() error = %v", err)
	}
	for {
		frame := readFrame(t, clientConn)
		body, err := mir176.UnwrapFrame(frame)
		if err != nil {
			t.Fatalf("UnwrapFrame() error = %v", err)
		}
		if strings.HasPrefix(string(body), "+GOOD/") {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for cached fire hit acknowledgement")
		}
	}
	<-done
	if ch.FireHitArmed {
		t.Fatal("character fire state remains armed after cached fire hit")
	}
	updatedMonsters, _ := s.world.SnapshotAround(ch.MapID, 0, 0, 99999)
	for _, updated := range updatedMonsters {
		if updated.ID != mon.ID {
			continue
		}
		if initialMonsterHP-updated.HP < 5 {
			t.Fatalf("cached fire hit damage = %d, want fire bonus applied", initialMonsterHP-updated.HP)
		}
		return
	}
	t.Fatalf("monster %q missing after cached fire hit", mon.ID)
}

