	caster.MP = cost + 10

	targetX, targetY := -1, -1
	for dx := 4; dx <= 8 && targetX < 0; dx++ {
		for dy := -2; dy <= 2; dy++ {
			tx := x + dx
			ty := y + dy
			if !mp.Walkable(tx, ty) || !mp.Walkable(tx+1, ty) {
				continue
			}
			targetX, targetY = tx, ty
			break
		}
	}
