	defer server.Close()
	defer client.Close()
	targetServer, targetClient := net.Pipe()
	defer targetServer.Close()
	defer targetClient.Close()
	targetObserverServer, targetObserverClient := net.Pipe()
	defer targetObserverServer.Close()
	defer targetObserverClient.Close()
