func TestHandleQueryUserNameRepliesWithNameOrGhost(t *testing.T) {
	s := newTestServer(t)
	mapID, x, y := testDefaultSpawn(t)
	ch, err := s.world.CreateCharacterWithAppearance("test", "tester", "warrior", 0, 0, mapID, x, y)
	if err != nil {
		t.Fatalf("CreateCharacter() error = %v", err)
	}

	t.Run("name", func(t *testing.T) {
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()

		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: world.CharacterActorID(ch), Param: uint16(ch.X), Tag: uint16(ch.Y)})
		}()

		cmd, body, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode reply error = %v", err)
		}
		if cmd.Ident != mir176.SMUserName {
			t.Fatalf("reply ident = %d, want SM_USERNAME (%d)", cmd.Ident, mir176.SMUserName)
		}
		if cmd.Recog != world.CharacterActorID(ch) || cmd.Param != 255 {
			t.Fatalf("reply header = %+v, want recog=%d param=255", cmd, world.CharacterActorID(ch))
		}
		decoded, err := mir176.DecodePlain6Payload(body)
		if err != nil {
			t.Fatalf("DecodePlain6Payload() error = %v", err)
		}
		if got := DecodeString(decoded); got != s.world.CharacterDisplayName(ch) {
			t.Fatalf("reply body = %q, want %q", got, s.world.CharacterDisplayName(ch))
		}
		<-done
	})

	t.Run("ghost", func(t *testing.T) {
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()

		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: world.CharacterActorID(ch), Param: uint16(ch.X + 2), Tag: uint16(ch.Y + 2)})
		}()

		cmd, _, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode reply error = %v", err)
		}
		if cmd.Ident != mir176.SMGhost {
			t.Fatalf("reply ident = %d, want SM_GHOST (%d)", cmd.Ident, mir176.SMGhost)
		}
		if cmd.Recog != world.CharacterActorID(ch) || int(cmd.Param) != ch.X+2 || int(cmd.Tag) != ch.Y+2 {
			t.Fatalf("ghost reply = %+v, want recog=%d x=%d y=%d", cmd, world.CharacterActorID(ch), ch.X+2, ch.Y+2)
		}
		<-done
	})

	t.Run("ghost target", func(t *testing.T) {
		ch.Ghost = true
		defer func() { ch.Ghost = false }()
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		ghost := ch
		ghost.Ghost = true
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: world.CharacterActorID(ghost), Param: uint16(ghost.X), Tag: uint16(ghost.Y)})
		}()
		cmd, _, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode ghost target reply error = %v", err)
		}
		if cmd.Ident != mir176.SMGhost {
			t.Fatalf("ghost target reply ident = %d, want SM_GHOST (%d)", cmd.Ident, mir176.SMGhost)
		}
		<-done
	})

	t.Run("monster", func(t *testing.T) {
		spawned, err := s.world.SpawnMonsterByNameAt(mapID, x+1, y, "鸡", 1)
		if err != nil || len(spawned.Monsters) != 1 {
			t.Fatalf("SpawnMonsterByNameAt() = %+v, %v", spawned.Monsters, err)
		}
		monster := spawned.Monsters[0]
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: world.MonsterActorID(monster), Param: uint16(monster.X), Tag: uint16(monster.Y)})
		}()
		cmd, body, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode monster reply error = %v", err)
		}
		decoded, err := mir176.DecodePlain6Payload(body)
		if err != nil {
			t.Fatalf("DecodePlain6Payload() error = %v", err)
		}
		if cmd.Ident != mir176.SMUserName || cmd.Recog != world.MonsterActorID(monster) || cmd.Param != world.MonsterNameColor(monster) || DecodeString(decoded) != world.MonsterDisplayName(monster) {
			t.Fatalf("monster reply = %+v body=%q", cmd, DecodeString(decoded))
		}
		<-done
	})

	t.Run("monster in nearby cell", func(t *testing.T) {
		spawned, err := s.world.SpawnMonsterByNameAt(mapID, x+1, y+1, "鸡", 1)
		if err != nil || len(spawned.Monsters) != 1 {
			t.Fatalf("SpawnMonsterByNameAt() = %+v, %v", spawned.Monsters, err)
		}
		monster := spawned.Monsters[0]
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: world.MonsterActorID(monster), Param: uint16(x), Tag: uint16(y)})
		}()
		cmd, _, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode nearby monster reply error = %v", err)
		}
		if cmd.Ident != mir176.SMUserName || cmd.Recog != world.MonsterActorID(monster) {
			t.Fatalf("nearby monster reply = %+v", cmd)
		}
		<-done
	})

	t.Run("npc", func(t *testing.T) {
		entity, ok := s.world.NPCByID("guide")
		if !ok {
			t.Fatal("missing guide NPC")
		}
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: s.world.NPCActorID(entity.ID), Param: uint16(entity.X), Tag: uint16(entity.Y)})
		}()
		cmd, body, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode NPC reply error = %v", err)
		}
		decoded, err := mir176.DecodePlain6Payload(body)
		if err != nil {
			t.Fatalf("DecodePlain6Payload() error = %v", err)
		}
		if cmd.Ident != mir176.SMUserName || cmd.Recog != s.world.NPCActorID(entity.ID) || cmd.Param != world.NPCNameColor(entity) || DecodeString(decoded) != world.NPCDisplayName(entity) {
			t.Fatalf("NPC reply = %+v body=%q", cmd, DecodeString(decoded))
		}
		<-done
	})

	t.Run("unknown target returns ghost", func(t *testing.T) {
		server, client := net.Pipe()
		defer server.Close()
		defer client.Close()
		done := make(chan struct{})
		go func() {
			defer close(done)
			s.handleQueryUserName(server, &ch, mir176.Command{Ident: mir176.CMQueryUserName, Recog: 100000, Param: uint16(x), Tag: uint16(y)})
		}()
		cmd, _, err := decodeMessageLikeClient(readFrame(t, client))
		if err != nil {
			t.Fatalf("decode unknown target reply error = %v", err)
		}
		if cmd.Ident != mir176.SMGhost || cmd.Recog != 100000 || int(cmd.Param) != x || int(cmd.Tag) != y {
			t.Fatalf("unknown target reply = %+v", cmd)
		}
		<-done
	})
}

